flowchart TD
  A["Recurrencia T(n)"] --> B{"¿Tiene forma T(n)=aT(n/b)+f(n)?"}
  B -- "No" --> X["No aplica Teorema Maestro\nUsar iteración, árbol, sustitución o ecuación característica"]
  B -- "Sí" --> C{"¿a ≥ 1 y b > 1?"}
  C -- "No" --> X
  C -- "Sí" --> D["Calcular p = log_b(a)"]
  D --> E{"Comparar f(n) con n^p"}
  E -- "f(n) ∈ O(n^(p-ε))" --> F["Caso 1\nT(n)=Θ(n^p)"]
  E -- "f(n) ∈ Θ(n^p)" --> G["Caso 2\nT(n)=Θ(n^p log n)"]
  E -- "f(n) ∈ Ω(n^(p+ε))" --> H{"¿Regularidad?\na f(n/b) ≤ c f(n), 0<c<1"}
  H -- "Sí" --> I["Caso 3\nT(n)=Θ(f(n))"]
  H -- "No" --> X
  E -- "Entre casos / sin ε" --> X
